1	import { useState, useEffect, useCallback, FormEvent } from "react";
2	import {
3	  Dialog,
4	  DialogContent,
5	  DialogHeader,
6	  DialogTitle,
7	  DialogFooter,
8	} from "@/components/ui/dialog";
9	import { Button } from "@/components/ui/button";
10	import { Input } from "@/components/ui/input";
11	import { Textarea } from "@/components/ui/textarea";
12	import { Label } from "@/components/ui/label";
13	import { useStoryStore } from "@/hooks/useStoryStore";
14	import { useMemberStore } from "@/hooks/useMemberStore";
15	import { toast } from "sonner";
16	import { Story, StoryInput } from "@/types/story";
17	import { MultiSelect } from "@/components/ui/multi-select";
18	import { useTranslation } from "react-i18next";
19	import { useUnsavedGuard } from "@/hooks/useUnsavedGuard";
20	import { getMemberOptions } from "@/utils/memberUtils";
21	import { DocumentLinkField } from "./DocumentLinkField";
22	import { PartialDatePicker } from "@/components/ui/partial-date-picker";
23	
24	interface StoryDialogProps {
25	  open: boolean;
26	  onOpenChange: (open: boolean) => void;
27	  story?: Story | null;
28	  initialMemberId?: string;
29	}
30	
31	export const StoryDialog = ({
32	  open,
33	  onOpenChange,
34	  story,
35	  initialMemberId,
36	}: StoryDialogProps) => {
37	  const { t, i18n } = useTranslation(undefined, {
38	    keyPrefix: "sheet.member-sheet.stories.dialog",
39	  });
40	  const { addStory, updateStory } = useStoryStore();
41	  const { members } = useMemberStore();
42	  const [formData, setFormData] = useState<StoryInput>({
43	    title: "",
44	    content: "",
45	  });
46	  const [selectedMemberIds, setSelectedMemberIds] = useState<string[]>([]);
47	  const [selectedDocumentIds, setSelectedDocumentIds] = useState<string[]>([]);
48	  const [submitting, setSubmitting] = useState(false);
49	
50	  const [initialSnapshot, setInitialSnapshot] = useState<{
51	    formData: StoryInput;
52	    selectedMemberIds: string[];
53	    selectedDocumentIds: string[];
54	  } | null>(null);
55	
56	  useEffect(() => {
57	    if (!open) {
58	      setInitialSnapshot(null);
59	      return;
60	    }
61	    if (story) {
62	      const snap = {
63	        formData: {
64	          title: story.title,
65	          content: story.content,
66	          date: story.date,
67	        },
68	        selectedMemberIds: story.linkedMemberIds || [],
69	        selectedDocumentIds: story.documentIds || [],
70	      };
71	      setInitialSnapshot(snap);
72	      setFormData(snap.formData);
73	      setSelectedMemberIds(snap.selectedMemberIds);
74	      setSelectedDocumentIds(snap.selectedDocumentIds);
75	    } else {
76	      const ids = initialMemberId ? [initialMemberId] : [];
77	      setInitialSnapshot({
78	        formData: { title: "", content: "", date: null },
79	        selectedMemberIds: ids,
80	        selectedDocumentIds: [],
81	      });
82	      setFormData({ title: "", content: "", date: null });
83	      setSelectedMemberIds(ids);
84	      setSelectedDocumentIds([]);
85	    }
86	  }, [story, initialMemberId, open]);
87	
88	  const isDirty =
89	    initialSnapshot !== null &&
90	    (formData.title !== initialSnapshot.formData.title ||
91	      formData.content !== initialSnapshot.formData.content ||
92	      JSON.stringify(selectedMemberIds) !==
93	        JSON.stringify(initialSnapshot.selectedMemberIds) ||
94	      JSON.stringify(selectedDocumentIds) !==
95	        JSON.stringify(initialSnapshot.selectedDocumentIds));
96	
97	  const save = useCallback(async (): Promise<boolean> => {
98	    setSubmitting(true);
99	    try {
100	      if (story) {
101	        await updateStory(
102	          story.id,
103	          formData,
104	          selectedMemberIds,
105	          selectedDocumentIds,
106	        );
107	      } else {
108	        await addStory(selectedMemberIds, formData, selectedDocumentIds);
109	      }
110	      onOpenChange(false);
111	      return true;
112	    } catch {
113	      toast.error(t("error-save"));
114	      return false;
115	    } finally {
116	      setSubmitting(false);
117	    }
118	    // eslint-disable-next-line react-hooks/exhaustive-deps
119	  }, [
120	    story,
121	    formData,
122	    selectedMemberIds,
123	    selectedDocumentIds,
124	    addStory,
125	    updateStory,
126	    onOpenChange,
127	  ]);
128	
129	  const handleSubmit = (e: FormEvent) => {
130	    e.preventDefault();
131	    // Stop the submit from bubbling through the portal to the surrounding
132	    // member-edit form, which would save the member and close the sheet.
133	    e.stopPropagation();
134	    void save();
135	  };
136	
137	  useUnsavedGuard("story", isDirty, save);
138	
139	  const memberOptions = getMemberOptions(members, (name) =>
140	    i18n.t("common.nee", { name }),
141	  );
142	
143	  return (
144	    <Dialog open={open} onOpenChange={onOpenChange}>
145	      <DialogContent className="sm:max-w-150 max-h-[80vh] flex flex-col">
146	        <DialogHeader>
147	          <DialogTitle>{story ? t("title-edit") : t("title-add")}</DialogTitle>
148	        </DialogHeader>
149	        <form
150	          onSubmit={handleSubmit}
151	          className="space-y-4 flex flex-col flex-1 min-h-0"
152	        >
153	          <div className="space-y-4 py-4 px-1 flex-1 overflow-y-auto">
154	            <div className="space-y-2">
155	              <Label htmlFor="members">{t("linked-members")} *</Label>
156	              <MultiSelect
157	                options={memberOptions}
158	                onValueChange={setSelectedMemberIds}
159	                defaultValue={selectedMemberIds}
160	                placeholder={t("linked-members-placeholder")}
161	                variant="inverted"
162	                maxCount={5}
163	                hideSelectedOptions
164	              />
165	              <p className="text-xs text-muted-foreground">
166	                {t("linked-members-description")}
167	              </p>
168	            </div>
169	
170	            <div className="space-y-2">
171	              <Label htmlFor="title">{t("title")} *</Label>
172	              <Input
173	                id="title"
174	                value={formData.title}
175	                onChange={(e) =>
176	                  setFormData({ ...formData, title: e.target.value })
177	                }
178	                placeholder={t("title-placeholder")}
179	                required
180	              />
181	            </div>
182	
183	            <div className="space-y-2">
184	              <Label htmlFor="content">{t("story")}</Label>
185	              <Textarea
186	                id="content"
187	                value={formData.content}
188	                onChange={(e) =>
189	                  setFormData({ ...formData, content: e.target.value })
190	                }
191	                placeholder={t("story-placeholder")}
192	                rows={10}
193	                className="resize-none"
194	              />
195	            </div>
196	
197	            <div className="space-y-2">
198	              <Label htmlFor="date">{t("date")}</Label>
199	              <PartialDatePicker
200	                placeholder={t("date-placeholder")}
201	                value={formData.date ?? null}
202	                onChange={(date) => setFormData({ ...formData, date })}
203	              />
204	              <p className="text-xs text-muted-foreground">
205	                {t("date-description")}
206	              </p>
207	            </div>
208	
209	            <DocumentLinkField
210	              documentIds={selectedDocumentIds}
211	              onChange={setSelectedDocumentIds}
212	              seedMemberIds={selectedMemberIds}
213	            />
214	          </div>
215	
216	          <DialogFooter>
217	            <Button
218	              type="button"
219	              variant="outline"
220	              size="sm"
221	              onClick={() => onOpenChange(false)}
222	            >
223	              {t("cancel")}
224	            </Button>
225	            <Button
226	              type="submit"
227	              size="sm"
228	              disabled={
229	                submitting || !formData.title || selectedMemberIds.length === 0
230	              }
231	            >
232	              {story ? t("update") : t("add")}
233	            </Button>
234	          </DialogFooter>
235	        </form>
236	      </DialogContent>
