  description: null,
  documentDate: null,
  createdAt: "2026-01-01T00:00:00Z",
  updatedAt: "2026-01-01T00:00:00Z",
  files: [],
  memberIds,
  eventIds: [],
  storyIds: [],
});

const OWN_DOC = doc("doc-own", "Own document", ["member-1"]);
const OTHER_DOC = doc("doc-other", "Other member's document", ["member-2"]);
